"use client";
import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "next/navigation";
import { Button, ErrorState, IconButton, Input, PageHeader, Skeleton, useFlags } from "@/components/ui";
import { useResource } from "@/lib/useFetch";
import * as R from "@/lib/services/reports";
import ReportsNav from "./ReportsNav";

/* The team's daily PDF reports (generated by the server at the configured
   hour). View inline, download; ?open=<id> from a notification.
   As in Odoo's Daily Task Reports: search by date, group by month, and
   "Generate yesterday's report" on demand. */
const monthLabel = (ymd) => { const d = new Date(`${ymd}T00:00:00`); return Number.isNaN(d.getTime()) ? "Undated" : d.toLocaleString(undefined, { month: "long", year: "numeric" }); };

export default function DailyReports() {
  const sp = useSearchParams();
  const flags = useFlags();
  const list = useResource(R.DAILY_PATH, { limit: 90 }, { ttl: 60000 });
  /* {status:false, message} is a refusal, not data. */
  const listData = list.data?.status === false ? null : list.data;
  const listErr = list.error || (list.data?.status === false ? new Error(list.data.message || "Could not load the daily reports.") : null);
  const reports = useMemo(() => listData?.reports || [], [listData]);
  const [open, setOpen] = useState(null);
  const [day, setDay] = useState("");
  const [byMonth, setByMonth] = useState(false);
  const [busy, setBusy] = useState(false);
  useEffect(() => { const id = +sp.get("open"); if (id && reports.length) setOpen(reports.find((r) => r.id === id) || { id }); }, [sp, reports]);

  const shown = useMemo(() => (day ? reports.filter((r) => r.report_date === day) : reports), [reports, day]);
  const groups = useMemo(() => {
    if (!byMonth) return [["", shown]];
    const m = new Map();
    for (const r of shown) { const k = (r.report_date || "").slice(0, 7) || "—"; if (!m.has(k)) m.set(k, []); m.get(k).push(r); }
    return [...m.entries()];
  }, [shown, byMonth]);

  const generateNow = async () => {
    setBusy(true);
    try { await R.generateDailyNow(); flags.ok("Yesterday's report is ready."); await list.refresh(); }
    catch (e) { flags.err(e.message || "Could not generate the report."); }
    finally { setBusy(false); }
  };

  return (
    <>
      <PageHeader crumbs={[{ label: "Reports" }, { label: "Daily reports" }]} title="Daily reports" meta="Generated every day at the hour set in Configuration">
        <Button kind="primary" busy={busy} onClick={generateNow} title="Build the report for yesterday now">Generate yesterday&apos;s report</Button>
      </PageHeader>
      <div className="page">
        <ReportsNav />
        <div className="toolbar">
          <Input type="date" value={day} onChange={(e) => setDay(e.target.value)} aria-label="Report date" style={{ width: 170, height: 32 }} />
          {day && <Button size="sm" kind="ghost" onClick={() => setDay("")}>Any date</Button>}
          <label className="chk" style={{ fontSize: 12.5 }}><input type="checkbox" checked={byMonth} onChange={(e) => setByMonth(e.target.checked)} />Group by month</label>
          {listData && <span className="right mini">{shown.length} of {reports.length} reports</span>}
        </div>
        {listErr && !listData && <ErrorState error={listErr} onRetry={list.refresh} />}
        <div className="g12" style={{ gridTemplateColumns: open ? "minmax(0, 1fr) minmax(0, 1.2fr)" : "minmax(0, 1fr)", flex: 1, minHeight: 0 }}>
          <div className="cardbox table-scroll" style={{ padding: 0 }}>
            {!listData && !listErr ? <div style={{ padding: 16 }}><Skeleton rows={6} /></div> : !listData ? null : (
              <table className="table">
                <thead><tr><th>Date</th><th className="num">Developers</th><th className="num">Tasks</th><th>Generated</th><th>File</th><th></th></tr></thead>
                <tbody>
                  {groups.map(([g, rs]) => [
                    byMonth ? <tr key={`g-${g}`} className="group"><td colSpan={6}>{monthLabel(`${g}-01`)} · {rs.length}</td></tr> : null,
                    ...rs.map((r) => (
                      <tr key={r.id} className={open?.id === r.id ? "sel" : ""} style={{ cursor: "pointer" }} onClick={() => setOpen(r)}>
                        <td><b>{r.date_display || r.report_date}</b></td><td className="num">{r.employee_count}</td><td className="num">{r.task_count}</td><td className="mini">{r.generated_at}</td>
                        <td className="mini">{r.has_file === false ? "No PDF yet" : r.file_name}</td>
                        <td><span style={{ display: "inline-flex", gap: 6 }}><Button size="sm" onClick={(e) => { e.stopPropagation(); setOpen(r); }} disabled={r.has_file === false}>View</Button><a className="btn" style={{ height: 28, fontSize: 12.5, textDecoration: "none" }} href={R.dailyDownloadHref(r.id)} onClick={(e) => e.stopPropagation()}>Download</a></span></td>
                      </tr>
                    )),
                  ])}
                  {list.data && !shown.length && <tr><td colSpan={6} className="empty">{day ? "No report for that date." : "No daily reports yet."}</td></tr>}
                </tbody>
              </table>
            )}
          </div>
          {open && (
            <div className="cardbox" style={{ padding: 0, overflow: "hidden", minHeight: 520 }}>
              <h2 style={{ padding: "14px 16px 0" }}>Daily report — {open.date_display || open.report_date || `#${open.id}`}<span className="right"><a className="btn" style={{ height: 28, fontSize: 12, textDecoration: "none" }} href={R.dailyDownloadHref(open.id)}>Download</a><IconButton icon="x" label="Close" size={16} onClick={() => setOpen(null)} /></span></h2>
              <iframe title="Daily report" src={R.dailyViewHref(open.id)} style={{ flex: 1, minHeight: 560, border: 0, margin: "12px 16px 16px", borderRadius: 10, background: "var(--hover)" }} />
            </div>
          )}
        </div>
      </div>
    </>
  );
}
